import re
from typing import Any


def od_rows(type_slug: str, q: str = "") -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    cursor: str | None = None
    for _ in range(100):
        if q:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor, q=q)
        else:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor)
        out.extend(page.get("records") or [])
        cursor = page.get("nextCursor")
        if not cursor:
            break
    return out


def od_data(row: Any) -> dict[str, Any]:
    return dict((row or {}).get("data") or {})


def od_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""


import csv
import io

FOLDER = "Order Desk/Import/"


def read_rows(name: str) -> list[dict[str, str]]:
    try:
        text = api.files.read(file=FOLDER + name)
    except Exception:
        return []
    return [{(k or "").strip().lower(): (v or "").strip() for k, v in row.items()} for row in csv.DictReader(io.StringIO(text.lstrip("﻿")))]


def truthy(value: str) -> bool:
    return value.strip().lower() in ("true", "yes", "y", "1")


def number(value: str, fallback: float) -> float:
    try:
        return float(value)
    except ValueError:
        return fallback


def save(type_slug: str, known: dict[str, dict[str, Any]], key: str, title: str, data: dict[str, Any], links: dict[str, Any]) -> dict[str, Any]:
    record: dict[str, Any] = {"title": title[:200], "data": data}
    if links:
        record["links"] = links
    if key in known:
        return api.records.update(type_slug=type_slug, record_id=known[key]["id"], record=record)
    row = api.records.create(type_slug=type_slug, record=record)
    known[key] = row
    return row


products: dict[str, dict[str, Any]] = {od_text(od_data(r).get("item_code")).upper(): r for r in od_rows("od_products")}
product_count = 0
for row in read_rows("products.csv"):
    code = row.get("item_code", "")
    if not code or not row.get("name"):
        continue
    data: dict[str, Any] = {"item_code": code, "sell_unit": row.get("sell_unit", "each") or "each", "category": row.get("category", ""), "active": truthy(row.get("active", "true") or "true")}
    if row.get("base_unit"):
        data["base_unit"] = row["base_unit"]
    if row.get("units_per_pack"):
        data["units_per_pack"] = number(row["units_per_pack"], 1)
    save("od_products", products, code.upper(), row["name"], data, {})
    product_count += 1
profiles: dict[str, dict[str, Any]] = {od_text(od_data(r).get("account_code")).upper(): r for r in od_rows("od_customer_profiles")}
customer_count = 0
for row in read_rows("customers.csv"):
    code = row.get("account_code", "")
    if not code or not row.get("name"):
        continue
    save("od_customer_profiles", profiles, code.upper(), row["name"], {"account_code": code, "email_domain": row.get("email_domain", ""), "other_names": row.get("other_names", ""), "order_notes": row.get("order_notes", ""), "order_rules": row.get("order_rules", ""), "cutoff_time": row.get("cutoff_time", "")[:5], "po_required": truthy(row.get("po_required", "")), "auto_confirm": "never" if row.get("auto_confirm", "").lower() == "never" else "follow_default"}, {})
    customer_count += 1
addresses: dict[str, dict[str, Any]] = {(od_text(od_data(r).get("account_code")) + "|" + od_text(r.get("title"))).upper(): r for r in od_rows("od_delivery_addresses")}
address_count = 0
for row in read_rows("delivery_addresses.csv"):
    if not row.get("label") or not row.get("address"):
        continue
    save("od_delivery_addresses", addresses, (row.get("account_code", "") + "|" + row["label"]).upper(), row["label"], {"account_code": row.get("account_code", ""), "address": row["address"], "site_code": row.get("site_code", ""), "is_default": truthy(row.get("is_default", ""))}, {})
    address_count += 1


def mapping_key(d: dict[str, Any]) -> str:
    return "|".join([od_text(d.get("account_code")), od_text(d.get("customer_code")), od_text(d.get("customer_unit")), od_text(d.get("item_code")), od_text(d.get("customer_description")) if not od_text(d.get("customer_code")) else ""]).upper()


catalogue: dict[str, dict[str, Any]] = {mapping_key(od_data(r)): r for r in od_rows("od_customer_catalogue")}
catalogue_count = 0
skipped = 0
for row in read_rows("customer_catalogue.csv"):
    account = row.get("account_code", "")
    item = row.get("item_code", "")
    if not account or not item:
        continue
    if item.upper() not in products:
        skipped += 1
        continue
    rounding = row.get("rounding", "none").lower()
    data = {"account_code": account, "customer_code": row.get("customer_code", ""), "customer_description": row.get("customer_description", ""), "customer_unit": row.get("customer_unit", ""), "item_code": item, "conversion_factor": number(row.get("conversion_factor", "1") or "1", 1), "rounding": rounding if rounding in ("none", "up", "down", "nearest") else "none", "source": "imported"}
    save("od_customer_catalogue", catalogue, mapping_key(data), account + " / " + (data["customer_code"] or data["customer_description"]) + " " + data["customer_unit"], data, {"product": [products[item.upper()]["id"]]})
    catalogue_count += 1
result = "Loaded " + str(product_count) + " products, " + str(customer_count) + " customers, " + str(address_count) + " addresses and " + str(catalogue_count) + " catalogue rows." + (" Skipped " + str(skipped) + " catalogue rows whose item code is not a product." if skipped else "")
